import { Skia } from "react-native-skia";

/** Shared SkSL: reads the light atlas per flicker cell (4 tiles × RGB = 12 cells), multiplies by each cell's brightness + linear colour. */
export const ATLAS_SKSL = `
uniform float bright[12];
uniform float3 col[12];
uniform float2 view;       // design frame (440×956 pt)
uniform float2 aTile;      // px per tile of atlas A
uniform float  aK;         // px atlas A / pt

float lum(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }

float hash21(float2 p) {
  p = fract(p * float2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
`;

/** Reads one atlas (SkSL can't take a child shader as a parameter → generates one function per atlas). */
export const atlasFn = (fn: string, child: string, tile: string, k: string) => `
float3 ${fn}(float2 p) {
  float2 q = clamp(p * ${k}, float2(0.5), ${tile} - 0.5);
  float3 acc = float3(0.0);
  for (int t = 0; t < 4; t++) {
    if (bright[t * 3] + bright[t * 3 + 1] + bright[t * 3 + 2] <= 0.0) continue;
    float3 s = float3(${child}.eval(q + float2(float(t) * ${tile}.x, 0.0)).rgb);
    acc += s.r * bright[t * 3] * col[t * 3]
         + s.g * bright[t * 3 + 1] * col[t * 3 + 1]
         + s.b * bright[t * 3 + 2] * col[t * 3 + 2];
  }
  return acc;
}
`;

/**
 * Brick wall + ground + puddles, lit by the neon (PLAN section 4).
 *  - Base: ambient.jpg (cold street light, dark). The neon adds: albedo · light · (N·L) · AO + specular on wet streaks.
 *  - Light at a point = atlas A (large blur of the tubes) × brightness × colour per cell; light direction L follows its gradient
 *    (towards the tubes), fixed z → brick edges and mortar joints facing the tubes light up, the other side is dark.
 *  - Puddles (data.b): flipped around the wall base (compressed by reflK), distorted by ripples + drop rings, adds the wall's neon
 *    at the reflected point + sharp tubes (atlas B), blur grows with distance, simple Fresnel.
 */
export const wall = Skia.RuntimeEffect.Make(`
uniform shader ambient;
uniform shader albedo;
uniform shader normalMap;
uniform shader dataMap;
uniform shader lightA;
uniform shader lightB;
${ATLAS_SKSL}
uniform float  imgK;       // scene image px / pt
uniform float2 bTile;
uniform float  bK;
uniform float  horizon;
uniform float  reflK;
uniform float  time;
uniform float  gain;       // neon intensity on the wall
uniform float  relief;     // normal-map relief 0..1
uniform float2 tilt;
${atlasFn("lightAt", "lightA", "aTile", "aK")}
${atlasFn("tubesAt", "lightB", "bTile", "bK")}

float3 toLin(half3 c) { return pow(max(float3(c), float3(0.0)), float3(2.2)); }

// neon light added to the surface at p (linear)
float3 neonAt(float2 p, float3 alb, float3 n, float rough, float ao) {
  float3 L0 = lightAt(p);
  float I = lum(L0);
  if (I < 0.0004) return float3(0.0);
  float e = 5.0;
  float Ix = lum(lightAt(p + float2(e, 0.0)));
  float Iy = lum(lightAt(p + float2(0.0, e)));
  float2 g = float2(Ix - I, Iy - I) / e;                 // image: y down
  float2 dir = g / (I + 0.004) * 26.0;                   // relative gradient → light ray slope
  float3 L = normalize(float3(dir.x, -dir.y, 0.55));
  float nl = max(dot(n, L), 0.0) / L.z;
  float shade = mix(1.0, nl, relief);
  float3 diff = alb * L0 * shade * ao;
  float3 H = normalize(L + float3(0.0, 0.0, 1.0));
  float shin = mix(90.0, 6.0, rough);
  float spec = pow(max(dot(n, H), 0.0), shin) * (1.0 - rough) * (1.0 - rough) * 1.6;
  return (diff + L0 * spec * 0.35) * gain;
}

float3 surf(float2 p, out float refl) {
  float2 ip = p * imgK;
  float3 alb = toLin(albedo.eval(ip).rgb);
  float3 n = normalize(float3(normalMap.eval(ip).rgb) * 2.0 - 1.0);
  half4 d = dataMap.eval(ip);
  refl = float(d.b);
  return neonAt(p, alb, n, float(d.r), mix(0.35, 1.0, float(d.g)));
}

float2 ripple(float2 p) {
  float2 o = float2(sin(p.y * 0.42 + time * 2.3) * 0.9 + sin(p.x * 0.06 + p.y * 0.23 - time * 1.4) * 1.3,
                    sin(p.x * 0.11 + time * 1.7) * 0.6);
  for (int i = 0; i < 3; i++) {
    float per = 1.3 + float(i) * 0.41;
    float ti = time + float(i) * 0.57;
    float w = floor(ti / per);
    float u = fract(ti / per);
    float2 c = float2(30.0 + hash21(float2(w, float(i))) * (view.x - 60.0),
                      horizon + 26.0 + hash21(float2(float(i), w + 3.1)) * (view.y - horizon - 50.0));
    float2 dv = (p - c) * float2(1.0, 3.4);              // ring lies tilted for perspective
    float r = length(dv);
    float R = u * 46.0;
    float ring = exp(-pow((r - R) / 3.5, 2.0)) * (1.0 - u) * (1.0 - u);
    o += dv / (r + 0.001) * ring * 5.0;
  }
  return o;
}

half4 main(float2 p) {
  float2 ip = p * imgK;
  float3 amb = toLin(ambient.eval(ip).rgb);
  float refl;
  float3 c = amb + surf(p, refl);

  if (p.y > horizon - 2.0 && refl > 0.02) {
    float depth = clamp((p.y - horizon) / (view.y - horizon), 0.0, 1.0);
    float2 rp = ripple(p) * (0.4 + depth);
    float2 q = float2(p.x, horizon - (p.y - horizon) * reflK) + rp * float2(1.0, reflK);
    q.y = max(q.y, 2.0);
    float3 wallN = lightAt(q) * toLin(albedo.eval(q * imgK).rgb) * gain * 0.8;
    // reflected tubes: vertical blur grows with distance
    float s = 1.0 + depth * 7.0;
    float3 tb = (tubesAt(q + float2(0.0, s * 0.5)) + tubesAt(q - float2(0.0, s * 0.5))) * 0.5;
    float3 tubes = mix(tb, float3(lum(tb)), 0.25) * 1.7;
    float F = refl * mix(0.95, 0.45, depth);
    c += (wallN * 0.8 + tubes) * F;
  }
  // dither against banding in dark areas
  c = pow(max(c, float3(0.0)), float3(1.0 / 2.2)) + (hash21(p * 3.0 + fract(time)) - 0.5) / 255.0;
  return half4(half3(c), 1.0);
}`)!;
